/// Resolve the palette for a brand + brightness.
PdPalette pdPalette(PdBrand brand, Brightness brightness) {
  final light = brightness == Brightness.light;
  switch (brand) {
    case PdBrand.restoration:
      return light ? _restorationLight : _restorationDark;
    case PdBrand.finance:
      return light ? _financeLight : _financeDark;
    case PdBrand.construction:
      return light ? _constructionLight : _constructionDark;
  }
}

