/// The categorical scale for a brightness. Brand-invariant.
///
/// Indices are deliberately unnamed: pick one per category and keep it
/// stable, but do not depend on which hue you get. Adjacent indices are
/// spaced across the wheel, so assigning 0,1,2... in order stays legible.
List<PdCatSwatch> pdCategorical(Brightness brightness) =>
    brightness == Brightness.light ? _categoricalLight : _categoricalDark;

/// The swatch at [index], wrapping so a caller with more categories than
/// the scale has slots still gets a colour instead of throwing.
PdCatSwatch pdCat(int index, Brightness brightness) {
  final scale = pdCategorical(brightness);
  return scale[index % scale.length];
}

